public class FreightCalc {
    private static final String XINJIANG = "新疆";
    private static final String XIZANG = "西藏";
    private static final int REMOTE_SURCHARGE = 8;

    private final boolean remoteFeeEnabled;   // 来自现有配置

    public FreightCalc(boolean remoteFeeEnabled) {
        this.remoteFeeEnabled = remoteFeeEnabled;
    }

    public int calc(Req r) {
        int fee = tpl(r.tplId).first;
        if (r.weight > 1.0) {
            int extra = (int) Math.ceil(r.weight - 1.0);
            int unit = tpl(r.tplId).next;
            if (r.vip) unit = unit / 2;
            fee += extra * unit;
        }
        if (region(r.province) != null) fee += region(r.province).surcharge;
        if (r.cod) fee += 2;
        fee += calcRemoteFee(r);
        return fee;
    }

    /**
     * 新逻辑入口：开关开启且省份为新疆/西藏时收偏远附加费，其余一律返回 0，
     * 使关闭时 calc 的结果与改动前逐字节一致。
     */
    int calcRemoteFee(Req r) {
        if (!remoteFeeEnabled) return 0;
        if (!isRemoteProvince(r.province)) return 0;
        return REMOTE_SURCHARGE;
    }

    private static boolean isRemoteProvince(String province) {
        return XINJIANG.equals(province) || XIZANG.equals(province);
    }

    private static Tpl tpl(int tplId) {
        if (tplId == 1032) return new Tpl(18, 4);
        throw new IllegalArgumentException("unknown tplId: " + tplId);
    }

    private static Region region(String province) {
        if (XINJIANG.equals(province)) return new Region(3);
        if (XIZANG.equals(province)) return new Region(3);
        if ("广东".equals(province)) return new Region(0);
        return null;
    }

    public static class Req {
        public final int tplId;
        public final double weight;
        public final String province;
        public final boolean vip;
        public final boolean cod;

        public Req(int tplId, double weight, String province, boolean vip, boolean cod) {
            this.tplId = tplId;
            this.weight = weight;
            this.province = province;
            this.vip = vip;
            this.cod = cod;
        }
    }

