public class FreightCalc {

    /** 偏远地区附加费（元） */
    private static final int REMOTE_FEE = 8;
    private static final String XINJIANG = "新疆";
    private static final String XIZANG = "西藏";

    private final boolean remoteFeeEnabled;   // 来自现有配置

    public FreightCalc(boolean remoteFeeEnabled) {
        this.remoteFeeEnabled = remoteFeeEnabled;
    }

    public int calc(Req r) {
        int fee = tpl(r.tplId).first;
        if (r.weight > 1.0) {
            int extra = (int) Math.ceil(r.weight - 1.0);
            int unit = tpl(r.tplId).next;
            if (r.vip) unit = unit / 2;
            fee += extra * unit;
        }
        if (region(r.province) != null) fee += region(r.province).surcharge;
        fee += calcRemoteFee(r);
        if (r.cod) fee += 2;
        return fee;
    }

    /**
     * 新逻辑入口：开关开启且省份为新疆或西藏时收偏远附加费，其余一律返回 0。
     * 开关关闭时恒为 0，即所有请求（包括新疆）保持原行为。
     */
    int calcRemoteFee(Req r) {
        if (!remoteFeeEnabled) return 0;
        if (XINJIANG.equals(r.province) || XIZANG.equals(r.province)) return REMOTE_FEE;
        return 0;
    }

    // ---------------------------------------------------------------
    // 以下为本练习的自足脚手架：真实项目里 Req / 模板表 / 区域表来自外部。
    // ---------------------------------------------------------------

    public static class Req {
        public int tplId;
        public double weight;
        public String province;
        public boolean vip;
        public boolean cod;

        public Req(int tplId, double weight, String province, boolean vip, boolean cod) {
            this.tplId = tplId;
            this.weight = weight;
            this.province = province;
            this.vip = vip;
            this.cod = cod;
        }
    }

    public static class Tpl {
        public final int first;
        public final int next;

        Tpl(int first, int next) {
            this.first = first;
            this.next = next;
        }
    }

    public static class Region {
        public final int surcharge;

        Region(int surcharge) {
            this.surcharge = surcharge;
        }
    }

    private static final Map<Integer, Tpl> TPLS = new HashMap<>();
    private static final Map<String, Region> REGIONS = new HashMap<>();

    static {
        TPLS.put(1032, new Tpl(18, 4));

        REGIONS.put(XINJIANG, new Region(3));
        REGIONS.put(XIZANG, new Region(3));
        REGIONS.put("广东", new Region(0));
    }

    private Tpl tpl(int tplId) {
        return TPLS.get(tplId);
    }

    private Region region(String province) {
        return REGIONS.get(province);
    }
}

