import java.math.BigDecimal;
import java.util.Set;

/**
 * 偏远地区附加费查询：按省份名返回附加金额。
 * 无状态、无依赖，线程安全。
 */
public final class RemoteFeeLookup {

    private static final BigDecimal REMOTE_FEE = new BigDecimal("8");
    private static final BigDecimal NO_FEE = new BigDecimal("0");

    /** 归一化后的偏远省份。新增偏远地区只改这里。 */
    private static final Set<String> REMOTE_PROVINCES = Set.of("新疆", "西藏");

    /** 行政区划后缀，必须长的在前，否则 "新疆维吾尔自治区" 会被剥成 "新疆维吾尔"。 */
    private static final String[] SUFFIXES = {
            "维吾尔自治区", "壮族自治区", "回族自治区", "特别行政区",
            "自治区", "省", "市"
    };

    /**
     * @param province 省份名，可为 null 或带后缀
     * @return 偏远附加费，非偏远或无法识别时为 0
     */
    public BigDecimal feeOf(String province) {
        return REMOTE_PROVINCES.contains(normalize(province)) ? REMOTE_FEE : NO_FEE;
    }

    private static String normalize(String province) {
        if (province == null) {
            return "";
        }
        String name = province.replaceAll("\\s", "");
        for (String suffix : SUFFIXES) {
            if (name.length() > suffix.length() && name.endsWith(suffix)) {
                return name.substring(0, name.length() - suffix.length());
            }
        }
        return name;
    }
}
```

两处值得说的写法：

- `feeOf` 里没有 `if/else` 链，而是一次集合查询。加"内蒙古也算偏远"时只动 `REMOTE_PROVINCES` 一行，`feeOf` 不再被碰——Open/Closed Principle 的最小实现。
- null 在 `normalize` 里被吞成空串，而不是抛异常。这是刻意的：附加费查询是计价路径上的旁支，脏数据让它算 0 比让整单计价炸掉更合理。如果你的业务要求"省份缺失必须拦下来"，就把 null 改成 `throw new IllegalArgumentException`，我可以改。

