```java
package com.example.shipping;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertEquals;

class RemoteFeeLookupTest {

    private final RemoteFeeLookup lookup = new RemoteFeeLookup();

    @ParameterizedTest
    @ValueSource(strings = {"新疆", "西藏", "新疆维吾尔自治区", "西藏自治区", " 新疆 "})
    void 偏远省份收八元(String province) {
        assertFee("8", lookup.feeOf(province));
    }

    @ParameterizedTest
    @ValueSource(strings = {"广东", "广东省", "北京市", "内蒙古自治区", "火星"})
    void 其余省份不收费(String province) {
        assertFee("0", lookup.feeOf(province));
    }

    @ParameterizedTest
    @NullAndEmptySource
    void 空输入不收费(String province) {
        assertFee("0", lookup.feeOf(province));
    }

    @Test
    void 后缀不会被过度剥离() {
        // "省" 本身不该被剥成空串
        assertFee("0", lookup.feeOf("省"));
    }

    /** 用 compareTo 而非 equals：BigDecimal 的 equals 会比较 scale，8 与 8.0 不相等。 */
    private static void assertFee(String expected, BigDecimal actual) {
        assertEquals(0, new BigDecimal(expected).compareTo(actual),
                () -> "expected " + expected + " but was " + actual);
    }
}
```

测试按"偏远 / 非偏远 / 边界"三组切分，每组用 `@ParameterizedTest` 铺数据——Table-Driven Testing。`内蒙古自治区` 放在非偏远组是明确的负向断言：将来谁要改规则，这条会先红。

